function(container, tables) {
    // 業務ロジックモジュールをインポート
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.businessLogic || {};

    // 予測精度監視に必要な要素を取得
    const refreshBtn = container.querySelector('#refresh-accuracy-btn');
    const productSelect = container.querySelector('#product-select');
    const storeSelect = container.querySelector('#store-select');
    const periodSelect = container.querySelector('#period-select');
    const accuracyTable = container.querySelector('#accuracy-table tbody');
    const accuracyChart = container.querySelector('#accuracy-chart');
    const alertsContainer = container.querySelector('#accuracy-alerts');

    // 商品・店舗選択肢を初期化
    function initializeSelectors() {
        // 商品データを取得して選択肢に設定
        window.aivicApi.list('products').then(products => {
            productSelect.innerHTML = '<option value="">全商品</option>';
            products.forEach(product => {
                const option = document.createElement('option');
                option.value = product.id;
                option.textContent = product.name;
                productSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('商品データの取得に失敗しました');
        });

        // 店舗データを取得して選択肢に設定
        window.aivicApi.list('stores').then(stores => {
            storeSelect.innerHTML = '<option value="">全店舗</option>';
            stores.forEach(store => {
                const option = document.createElement('option');
                option.value = store.id;
                option.textContent = store.name;
                storeSelect.appendChild(option);
            });
        }).catch(error => {
            window.aivicNotify.error('店舗データの取得に失敗しました');
        });
    }

    // 予測精度を計算して表示
    function calculateAndDisplayAccuracy(salesData, period) {
        try {
            // 過去データとの比較を実行
            const comparisonResult = compareWithHistoricalData(salesData, period);

            // 精度テーブルを更新
            updateAccuracyTable(comparisonResult);

            // チャートを更新
            updateAccuracyChart(comparisonResult);

            // アラートを更新
            updateAccuracyAlerts(comparisonResult);

        } catch (error) {
            window.aivicNotify.error('予測精度の計算に失敗しました: ' + error.message);
        }
    }

    // 精度テーブルを更新
    function updateAccuracyTable(data) {
        if (!accuracyTable) return;

        accuracyTable.innerHTML = '';

        if (data && data.accuracyMetrics) {
            data.accuracyMetrics.forEach(metric => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${metric.productName || '全商品'}</td>
                    <td>${metric.storeName || '全店舗'}</td>
                    <td>${(metric.accuracy * 100).toFixed(1)}%</td>
                    <td>${metric.mae ? metric.mae.toFixed(2) : '-'}</td>
                    <td>${metric.rmse ? metric.rmse.toFixed(2) : '-'}</td>
                    <td><span class="status-badge ${metric.status}">${metric.statusText}</span></td>
                `;
                accuracyTable.appendChild(row);
            });
        }
    }

    // チャートを更新
    function updateAccuracyChart(data) {
        if (!accuracyChart) return;

        // 簡易チャート表示（実際の実装では Chart.js等を使用）
        if (data && data.chartData) {
            accuracyChart.innerHTML = `
                <div class="chart-placeholder">
                    <p>予測精度推移グラフ</p>
                    <div class="chart-bars">
                        ${data.chartData.map(item => 
                            `<div class="chart-bar" style="height: ${item.accuracy * 100}px" title="${item.date}: ${(item.accuracy * 100).toFixed(1)}%"></div>`
                        ).join('')}
                    </div>
                </div>
            `;
        }
    }

    // アラートを更新
    function updateAccuracyAlerts(data) {
        if (!alertsContainer) return;

        alertsContainer.innerHTML = '';

        if (data && data.alerts) {
            data.alerts.forEach(alert => {
                const alertDiv = document.createElement('div');
                alertDiv.className = `alert alert-${alert.level}`;
                alertDiv.innerHTML = `
                    <strong>${alert.title}</strong>
                    <p>${alert.message}</p>
                    ${alert.recommendation ? `<p class="recommendation">推奨: ${alert.recommendation}</p>` : ''}
                `;
                alertsContainer.appendChild(alertDiv);
            });
        }
    }

    // 予測精度データを更新
    async function refreshAccuracyData() {
        const productId = productSelect.value;
        const storeId = storeSelect.value;
        const period = periodSelect.value || '7';

        try {
            // 期間の妥当性をチェック
            const periodValidation = validateComparisonPeriod(parseInt(period));
            if (!periodValidation.isValid) {
                window.aivicNotify.error(periodValidation.message);
                return;
            }

            // 売上データを収集
            const salesData = await collectSalesData();
            let filteredData = salesData;

            // 商品別にフィルタリング
            if (productId) {
                const productClassified = classifySalesDataByProduct(filteredData);
                filteredData = productClassified.filter(item => item.productId === productId);
            }

            // 店舗別にフィルタリング
            if (storeId) {
                const storeClassified = classifySalesDataByStore(filteredData);
                filteredData = storeClassified.filter(item => item.storeId === storeId);
            }

            // 有効な商品データのみ抽出
            const validData = filterValidProductData(filteredData);

            if (validData.length === 0) {
                // 代替データを探す
                const alternativeData = findAlternativeComparisonData(salesData, { productId, storeId });
                if (alternativeData.length > 0) {
                    calculateAndDisplayAccuracy(alternativeData, parseInt(period));
                    window.aivicNotify.warning('指定条件のデータが不足のため、類似データで表示しています');
                } else {
                    window.aivicNotify.error('表示可能なデータがありません');
                }
                return;
            }

            // 予測精度を計算して表示
            calculateAndDisplayAccuracy(validData, parseInt(period));

            // 相関分析データも取得して精度向上のヒントを表示
            try {
                const [weatherData, eventData, seasonalData] = await Promise.all([
                    collectWeatherData(),
                    collectEventData(),
                    collectSeasonalData()
                ]);

                // 相関分析を実行
                const weatherCorrelation = analyzeCorrelationSalesWeather(validData, weatherData);
                const eventCorrelation = analyzeCorrelationSalesEvent(validData, eventData);
                const seasonalCorrelation = analyzeCorrelationSalesSeason(validData, seasonalData);

                // 相関分析結果を表示（アラートとして）
                displayCorrelationInsights(weatherCorrelation, eventCorrelation, seasonalCorrelation);

            } catch (correlationError) {
                console.warn('相関分析でエラーが発生しました:', correlationError);
            }

        } catch (error) {
            window.aivicNotify.error('予測精度データの更新に失敗しました: ' + error.message);
        }
    }

    // 相関分析結果を表示
    function displayCorrelationInsights(weatherCorr, eventCorr, seasonalCorr) {
        const insights = [];

        if (weatherCorr && weatherCorr.correlation > 0.7) {
            insights.push({
                level: 'info',
                title: '天候との相関',
                message: `天候データとの相関が高く検出されました（相関係数: ${weatherCorr.correlation.toFixed(2)}）`,
                recommendation: '天候予報を予測モデルに組み込むことで精度向上が期待できます'
            });
        }

        if (eventCorr && eventCorr.correlation > 0.6) {
            insights.push({
                level: 'info',
                title: 'イベントとの相関',
                message: `イベントデータとの相関が検出されました（相関係数: ${eventCorr.correlation.toFixed(2)}）`,
                recommendation: 'イベント情報を予測に活用することを推奨します'
            });
        }

        if (seasonalCorr && seasonalCorr.seasonality > 0.5) {
            insights.push({
                level: 'info',
                title: '季節性パターン',
                message: `明確な季節性パターンが検出されました（季節性指数: ${seasonalCorr.seasonality.toFixed(2)}）`,
                recommendation: '季節調整を予測モデルに適用することを推奨します'
            });
        }

        // インサイトをアラートコンテナに追加
        if (insights.length > 0 && alertsContainer) {
            insights.forEach(insight => {
                const insightDiv = document.createElement('div');
                insightDiv.className = `alert alert-${insight.level}`;
                insightDiv.innerHTML = `
                    <strong>${insight.title}</strong>
                    <p>${insight.message}</p>
                    <p class="recommendation">推奨: ${insight.recommendation}</p>
                `;
                alertsContainer.appendChild(insightDiv);
            });
        }
    }

    // イベントハンドラーを設定
    if (refreshBtn) {
        refreshBtn.addEventListener('click', refreshAccuracyData);
    }

    // 選択肢変更時の自動更新
    [productSelect, storeSelect, periodSelect].forEach(select => {
        if (select) {
            select.addEventListener('change', refreshAccuracyData);
        }
    });

    // 初期化実行
    initializeSelectors();

    // 初期データ読み込み
    setTimeout(() => {
        refreshAccuracyData();
    }, 500);
}
